473	pub fn repl_dqi(args: &[&str]) {
474	    if args.is_empty() || args[0] == "help" {
475	        sprintln!("dqi — Decoded Quantum Interferometry operator (DQI word ⊢∈∈≻⋈⊤⊤⊥∋≺⋈∋⊣⊙, period 14)");
476	        sprintln!("  dqi word              print the canonical double-⊤ word");
477	        sprintln!("  dqi word single       print the single-⊤ variant (period 13)");
478	        sprintln!("  dqi period            print the period");
479	        sprintln!("  dqi phase             print whether the word is phase-bearing");
480	        sprintln!("  dqi verdict <string>  B4 verdict for a bit string (1/0 chars)");
481	        sprintln!("  dqi syndrome <bits>   syndrome-decode a bit string");
482	        sprintln!("  dqi tuple             print the catalog tuple");
483	        sprintln!("  dqi report            full DQI report");
484	        sprintln!("  dqi xorsat <m>        solve a random m-variable XOR system (Gaussian elimination), verify");
485	        sprintln!("  dqi decode <m> <ell>  weight-≤ell syndrome decode on a random m-variable code");
486	        sprintln!("  dqi benchmark <m>     elimination vs brute force on the same random instance (m≤24 runs both)");
487	        sprintln!("  dqi gpu-benchmark <m> [unsat] [device]  brute-force all 2^m assignments on GPU, cross-check vs elimination");
488	        sprintln!("                          add 'unsat' to force the worst case (no thread can exit early)");
489	        sprintln!("  Single-⊤ variant: ⊢∈∈≻⋈⊤⊥∋≺⋈∋⊣⊙ (period 13)");
490	        sprintln!("  Double-⊤ variant: ⊢∈∈≻⋈⊤⊤⊥∋≺⋈∋⊣⊙ (period 14)");
491	        sprintln!("  Triple-⊤ variant: ⊢∈∈≻⋈⊤⊤⊤⊥∋≺⋈∋⊣⊙ (period 15)");
492	        sprintln!("  Pattern: each ⊤ in the deposit phase extends the ROTAT period by 1.");
493	        return;
494	    }
495	    match args[0] {
496	        "word" => {
497	            if args.get(1).copied() == Some("single") {
498	                sprintln!("{}", WORD_SINGLE_T);
499	            } else {
500	                sprintln!("{}", WORD);
501	            }
502	        }
503	        "period" => sprintln!("{}", PERIOD),
504	        "phase" => sprintln!("{}", if PHASE_BEARING { "phase-bearing (3 distinct landings)" } else { "trivial" }),
505	        "verdict" => {
506	            let s = args.get(1).copied().unwrap_or("");
507	            sprintln!("{}", dqi_verdict(s));
508	        }
509	        "syndrome" => {
510	            let s = args.get(1).copied().unwrap_or("");
511	            let bits: alloc::vec::Vec<u8> = s.bytes()
512	                .filter(|b| *b == b'0' || *b == b'1')
513	                .map(|b| b - b'0')
514	                .collect();
515	            let decoded = dqi_syndrome_decode(&bits);
516	            let s_out: alloc::string::String = decoded.iter().map(|b| char::from(b'0' + b)).collect();
517	            sprintln!("{}", s_out);
518	        }
519	        "tuple" => sprintln!("⟨𐑨𐑶𐑽𐑿𐑐𐑘𐑔𐑠⊙𐑖𐑙𐑭⟩"),
520	        "xorsat" => {
521	            let m: usize = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(16);
522	            let (clauses, planted) = random_xorsat_instance(m, m as u64);
523	            match xorsat_solve(&clauses, m) {
524	                Some(a) => {
525	                    let ok = check_assignment(&clauses, &a);
526	                    let matches_planted = a == planted;
527	                    sprintln!(
528	                        "xorsat({} vars, {} clauses): SAT, verified={} matches_planted={}",
529	                        m, clauses.len(), ok, matches_planted
530	                    );
531	                }
532	                None => sprintln!("xorsat({} vars, {} clauses): UNSAT", m, clauses.len()),
533	            }
534	        }
535	        "decode" => {
536	            let m: usize = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(16);
