1	//! opi.rs — Optimal Polynomial Intersection, matched to the real paper.
2	//!
3	//! First version of this file built a simpler problem (single target
4	//! value per point) and, worse, its report compared a satisfaction
5	//! FRACTION against a number that was actually an expected COUNT
6	//! (n/p), not a fraction (1/p) -- a units error that only looked
7	//! sane because n happened to be near p. Caught by reading the actual
8	//! paper (Optimization_by_Decoded_Quantum_Interferometry.pdf, ig-docs)
9	//! instead of continuing to guess at "balanced." Rebuilt from
10	//! Definition 2.2 and §11.3 directly.
11	//!
12	//! Definition 2.2 (OPI): fix prime p and n < p-1. Let F_1..F_{p-1} be
13	//! subsets of GF(p). Find Q of degree ≤ n-1 maximizing the count of
14	//! y ∈ {1,...,p-1} with Q(y) ∈ F_y. §5 re-expresses this using a
15	//! primitive root γ of GF(p): the m = p-1 constraint points are
16	//! γ^0, ..., γ^{p-2}, and "balanced" (§5, eq. 15) means every F_i has
17	//! size ⌊p/2⌋ -- stated in the paper itself, not a construction I chose.
18	//! The sets F_i here are built as independent uniformly random
19	//! size-⌊p/2⌋ subsets of GF(p), matching the paper's own analysis
20	//! assumption "assuming the f_i are random" (§11.3).
21	//!
22	//! §11.3, Prange's algorithm, reproduced exactly: throw away all but n
23	//! of the m constraints, pick an arbitrary element of F_i for each kept
24	//! constraint, solve the resulting exactly-determined system (Lagrange
25	//! interpolation here), then measure how many of all m constraints the
26	//! resulting polynomial satisfies. Repeated over many trials. The
27	//! paper's own closed-form prediction (derived directly from its plain-
28	//! English description, cross-checked against its worked example: at
29	//! r/p=1/2, n/p=1/2, this gives 0.75, matching the paper's own quoted
30	//! number exactly):
31	//!   phi_PR = n/m + (1 - n/m) * (r/p),   r = floor(p/2), m = p-1.
32	//!
33	//! The paper's own DQI+Berlekamp-Massey asymptotic prediction (eq. 16,
34	//! m -> p limit), THEIR formula's output at these parameters:
35	//!   phi_DQI = 1/2 + sqrt( (n/2p) * (1 - n/2p) )
36	//! Cross-checked against the paper's own quoted n/p=1/2 example
37	//! (phi_DQI -> 0.9330): computed here as 1/2 + sqrt(0.25*0.75) =
38	//! 0.9330, matching to four digits.
39	//!
40	//! phi_PR's column is the real run: Prange's algorithm, measured. phi_DQI
41	//! is the paper's own closed-form prediction, evaluated at these
42	//! parameters, a citation standing next to the measurement it compares to.
43	
44	#![allow(dead_code)]
45	
46	use crate::sprintln;
47	use alloc::format;
48	use alloc::string::String;
49	use alloc::vec::Vec;
50	
51	struct Xorshift(u64);
52	impl Xorshift {
53	    fn next_u64(&mut self) -> u64 {
54	        let mut x = self.0;
55	        x ^= x << 13;
56	        x ^= x >> 7;
57	        x ^= x << 17;
58	        self.0 = x;
59	        x
60	    }
61	    fn next_below(&mut self, n: u64) -> u64 {
62	        self.next_u64() % n
63	    }
64	}
65	
66	fn add_mod(a: u64, b: u64, p: u64) -> u64 {
67	    (a + b) % p
68	}
69	fn sub_mod(a: u64, b: u64, p: u64) -> u64 {
70	    (a + p - (b % p)) % p
71	}
72	fn mul_mod(a: u64, b: u64, p: u64) -> u64 {
73	    ((a as u128 * b as u128) % p as u128) as u64
74	}
75	
76	fn mod_pow(base: u64, exp: u64, p: u64) -> u64 {
77	    let mut base = base % p;
78	    let mut exp = exp;
79	    let mut result = 1u64;
80	    while exp > 0 {
81	        if exp & 1 != 0 {
82	            result = mul_mod(result, base, p);
83	        }
84	        base = mul_mod(base, base, p);
85	        exp >>= 1;
86	    }
87	    result
88	}
89	
90	/// Modular inverse via Fermat's little theorem: a^(p-2) mod p, valid
91	/// whenever p is prime and a is not a multiple of p.
92	fn mod_inv(a: u64, p: u64) -> u64 {
93	    mod_pow(a, p - 2, p)
94	}
95	
96	fn is_prime(n: u64) -> bool {
97	    if n < 2 {
98	        return false;
99	    }
100	    let mut i = 2u64;
101	    while i * i <= n {
102	        if n % i == 0 {
103	            return false;
104	        }
105	        i += 1;
106	    }
107	    true
108	}
109	
110	/// Distinct prime factors of n, by trial division -- n here is always
111	/// p-1 for a modest prime p, small enough that trial division is exact
112	/// and fast.
113	fn distinct_prime_factors(mut n: u64) -> Vec<u64> {
114	    let mut factors = Vec::new();
115	    let mut d = 2u64;
116	    while d * d <= n {
117	        if n % d == 0 {
118	            factors.push(d);
119	            while n % d == 0 {
120	                n /= d;
121	            }
122	        }
123	        d += 1;
124	    }
125	    if n > 1 {
126	        factors.push(n);
127	    }
128	    factors
129	}
130	
131	/// A primitive root of GF(p): g such that g^((p-1)/q) != 1 mod p for
132	/// every prime factor q of p-1 -- the standard, exact test (not a
133	/// probabilistic guess), checked against every prime factor of p-1.
134	fn find_primitive_root(p: u64) -> u64 {
135	    let factors = distinct_prime_factors(p - 1);
136	    let mut g = 2u64;
137	    loop {
138	        if factors.iter().all(|&q| mod_pow(g, (p - 1) / q, p) != 1) {
139	            return g;
140	        }
141	        g += 1;
142	    }
143	}
144	
145	/// Lagrange interpolation over GF(p): the unique polynomial of degree
146	/// < points.len() passing exactly through every given (x, y) pair,
147	/// returned in coefficient form (index i = coefficient of x^i).
148	fn lagrange_interpolate(points: &[(u64, u64)], p: u64) -> Vec<u64> {
149	    let k = points.len();
150	    let mut coeffs = alloc::vec![0u64; k];
151	    for i in 0..k {
152	        let (xi, yi) = points[i];
153	        let mut basis = alloc::vec![0u64; k];
154	        basis[0] = 1;
155	        let mut degree = 0usize;
156	        let mut denom = 1u64;
157	        for j in 0..k {
158	            if j == i {
159	                continue;
160	            }
161	            let (xj, _) = points[j];
162	            let mut next = alloc::vec![0u64; k];
163	            for d in 0..=degree {
164	                if d + 1 < k {
165	                    next[d + 1] = add_mod(next[d + 1], basis[d], p);
166	                }
167	                next[d] = sub_mod(next[d], mul_mod(basis[d], xj, p), p);
168	            }
169	            basis = next;
170	            degree += 1;
171	            denom = mul_mod(denom, sub_mod(xi, xj, p), p);
172	        }
173	        let scale = mul_mod(yi, mod_inv(denom, p), p);
174	        for d in 0..k {
175	            coeffs[d] = add_mod(coeffs[d], mul_mod(basis[d], scale, p), p);
176	        }
177	    }
178	    coeffs
179	}
180	
181	fn eval_poly(coeffs: &[u64], x: u64, p: u64) -> u64 {
182	    let mut acc = 0u64;
183	    for &c in coeffs.iter().rev() {
184	        acc = add_mod(mul_mod(acc, x, p), c, p);
185	    }
186	    acc
187	}
188	
189	#[cfg(feature = "hosted")]
190	fn now_micros() -> i64 {
191	    use std::time::{SystemTime, UNIX_EPOCH};
192	    SystemTime::now()
193	        .duration_since(UNIX_EPOCH)
194	        .map(|d| d.as_micros() as i64)
195	        .unwrap_or(0)
196	}
197	
198	fn sqrt_f64(x: f64) -> f64 {
199	    libm::sqrt(x)
200	}
201	
202	pub struct OpiResult {
203	    pub p: u64,
204	    pub n: usize,
205	    pub m: usize,
206	    pub r: usize,
207	    pub gamma: u64,
208	    pub trials: usize,
209	    pub best_satisfied: usize,
210	    pub best_fraction: f64,
211	    pub phi_pr_theory: f64,
212	    pub phi_dqi_asymptotic: f64,
213	    #[cfg(feature = "hosted")]
214	    pub micros: i64,
215	}
216	
217	/// The real run, matched to Definition 2.2 and §11.3: m=p-1 constraint
218	/// points γ^0..γ^{p-2}, each with an independent random size-⌊p/2⌋
219	/// satisfying set (balanced, per eq. 15), Prange's algorithm run for
220	/// `trials` repetitions, best satisfaction fraction reported against
221	/// both the paper's own finite-size Prange prediction and its
222	/// asymptotic DQI+BM prediction.
223	pub fn run_opi(p: u64, n: usize, trials: usize, seed: u64) -> Result<OpiResult, String> {
224	    if !is_prime(p) {
225	        return Err(format!("p={} is not prime -- GF(p) arithmetic needs a prime field", p));
226	    }
227	    let m = (p - 1) as usize;
228	    if n == 0 || n >= m {
229	        return Err(format!("n={} must satisfy 0 < n < p-1={}", n, m));
230	    }
231	    let r = (p / 2) as usize;
232	    let gamma = find_primitive_root(p);
233	
234	    let mut rng = Xorshift(seed ^ 0x9E3779B97F4A7C15);
235	
236	    // The m=p-1 constraint points: gamma^0 .. gamma^{p-2}, every
237	    // nonzero field element exactly once (gamma is primitive).
238	    let points: Vec<u64> = {
239	        let mut v = Vec::with_capacity(m);
240	        let mut cur = 1u64;
241	        for _ in 0..m {
242	            v.push(cur);
243	            cur = mul_mod(cur, gamma, p);
244	        }
245	        v
246	    };
247	
248	    // Independent random size-r subset of GF(p) for each constraint --
249	    // the "balanced" instance, size stated by eq. 15, membership drawn
250	    // fresh per constraint (the paper's own "assuming the f_i are
251	    // random" analysis assumption, not a weaker stand-in for it).
252	    let sat_sets: Vec<Vec<bool>> = (0..m)
253	        .map(|_| {
254	            let mut membership = alloc::vec![false; p as usize];
255	            let mut count = 0usize;
256	            while count < r {
257	                let v = rng.next_below(p) as usize;
258	                if !membership[v] {
259	                    membership[v] = true;
260	                    count += 1;
261	                }
262	            }
263	            membership
264	        })
265	        .collect();
266	
267	    #[cfg(feature = "hosted")]
268	    let t0 = now_micros();
269	
270	    let mut best_satisfied = 0usize;
271	    for _ in 0..trials {
272	        // Prange: keep a random n of the m constraints.
273	        let mut idx: Vec<usize> = (0..m).collect();
274	        for i in 0..n {
275	            let j = i + rng.next_below((m - i) as u64) as usize;
276	            idx.swap(i, j);
277	        }
278	        let kept = &idx[..n];
279	        // For each kept constraint, pick an element of its F_i.
280	        let subset: Vec<(u64, u64)> = kept
281	            .iter()
282	            .map(|&i| {
283	                let members: Vec<u64> = (0..p).filter(|&v| sat_sets[i][v as usize]).collect();
284	                let pick = members[rng.next_below(members.len() as u64) as usize];
285	                (points[i], pick)
286	            })
287	            .collect();
288	        let coeffs = lagrange_interpolate(&subset, p);
289	        let satisfied = (0..m)
290	            .filter(|&i| sat_sets[i][eval_poly(&coeffs, points[i], p) as usize])
291	            .count();
292	        if satisfied > best_satisfied {
293	            best_satisfied = satisfied;
294	        }
295	    }
296	
297	    #[cfg(feature = "hosted")]
298	    let micros = now_micros() - t0;
299	
300	    let n_f = n as f64;
301	    let m_f = m as f64;
302	    let p_f = p as f64;
303	    let r_f = r as f64;
304	    let phi_pr_theory = n_f / m_f + (1.0 - n_f / m_f) * (r_f / p_f);
305	    let half_over_p = n_f / (2.0 * p_f);
306	    let phi_dqi_asymptotic = 0.5 + sqrt_f64(half_over_p * (1.0 - half_over_p));
307	
308	    Ok(OpiResult {
309	        p,
310	        n,
311	        m,
312	        r,
313	        gamma,
314	        trials,
315	        best_satisfied,
316	        best_fraction: best_satisfied as f64 / m as f64,
317	        phi_pr_theory,
318	        phi_dqi_asymptotic,
319	        #[cfg(feature = "hosted")]
320	        micros,
321	    })
322	}
323	
324	pub fn report(res: &OpiResult) -> String {
325	    let mut out = String::new();
326	    out.push_str(&format!(
327	        "opi: p={}, n={}, m=p-1={}, r=floor(p/2)={}, gamma={} (n/p={:.4})\n",
328	        res.p, res.n, res.m, res.r, res.gamma, res.n as f64 / res.p as f64
329	    ));
330	    out.push_str("  balanced (Def. 2.2, eq. 15): each of the m constraints has an independent random size-r satisfying set\n");
331	    out.push_str(&format!(
332	        "  Prange's algorithm (§11.3), {} trials: best {} / {} satisfied (fraction {:.4})\n",
333	        res.trials, res.best_satisfied, res.m, res.best_fraction
334	    ));
335	    out.push_str(&format!(
336	        "  Prange closed-form prediction n/m + (1-n/m)(r/p): {:.4}  (single-trial expectation; \"best\" above is the max over {} trials, so it is expected to run above this, per §11.3's own \"logarithmic number of standard deviations onto the tail\" argument)\n",
337	        res.phi_pr_theory, res.trials
338	    ));
339	    out.push_str(&format!(
340	        "  paper's DQI+BM asymptotic prediction (eq. 16): {:.4}\n",
341	        res.phi_dqi_asymptotic
342	    ));
343	    #[cfg(feature = "hosted")]
344	    out.push_str(&format!("  runtime: {} us ({:.3} ms)\n", res.micros, res.micros as f64 / 1000.0));
345	    out
346	}
