    pub phi_pr_theory: f64,
    pub ell: usize,
    pub lambda_max: f64,
    pub phi_dqi_exact: f64,
    pub phi_dqi_asymptotic: f64,
    #[cfg(feature = "hosted")]
    pub micros: i64,
}

