fn sqrt_f64(x: f64) -> f64 {
    libm::sqrt(x)
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { -x } else { x }
}

/// Lemma 9.2's (ℓ+1)×(ℓ+1) real symmetric tridiagonal matrix A^(m,ℓ,d):
/// diagonal entries k*d for k=0..=ell, off-diagonals a_k = sqrt(k(m-k+1))
