    for i in 0..dim {
        let mut row = abs_f64(diag[i]);
        if i > 0 {
            row += abs_f64(off[i - 1]);
        }
        if i < dim - 1 {
            row += abs_f64(off[i]);
        }
        if row > shift {
            shift = row;
        }
    }

    let mut v = alloc::vec![1.0f64; dim];
    let mut norm = sqrt_f64(v.iter().map(|x| x * x).sum());
    for x in v.iter_mut() {
        *x /= norm;
    }

    for _ in 0..2000 {
        let mut w = alloc::vec![0.0f64; dim];
        for i in 0..dim {
            let mut wi = (diag[i] + shift) * v[i];
            if i > 0 {
                wi += off[i - 1] * v[i - 1];
            }
            if i < dim - 1 {
                wi += off[i] * v[i + 1];
            }
            w[i] = wi;
        }
